(function () {
  'use strict';

  // 撮影用アプリ427の初期カスタマイズ。PCの追加・編集保存時に確認する。
  const THRESHOLD_YEN = 30000;
  const REASON_CODE = '高額申請の理由';
  const MESSAGE = '3万円以上の申請には、高額申請の理由を入力してください。';

  kintone.events.on(['app.record.create.submit', 'app.record.edit.submit'], function (event) {
    if (String(event.appId) !== '427') return event;
    const record = event.record;
    const reason = record[REASON_CODE];
    if (!reason || !record['精算金額']) return event;
    const amount = Number(record['精算金額'].value);
    const reasonIsEmpty = reason.value === undefined || reason.value === null || String(reason.value).trim() === '';
    if (Number.isFinite(amount) && amount >= THRESHOLD_YEN && reasonIsEmpty) {
      reason.error = MESSAGE;
    } else if (reason.error === MESSAGE) {
      // このJSが設定したエラーだけを解除し、ほかのチェック結果は維持する。
      reason.error = null;
    }
    return event;
  });
})();

