  'use strict';

  const EVENTS = ['app.record.create.submit', 'app.record.edit.submit'];
  const TARGET_METHODS = ['電車', 'バス', 'タクシー'];

  function validateLocation(field, required, message) {
    const value = field.value;
    const empty = value === undefined || value === null || String(value).trim() === '';
    if (required && empty) {
      if (!field.error) {
        field.error = message;
      }
    } else if (field.error === message) {
      field.error = null;
    }
  }

  kintone.events.on(EVENTS, (event) => {
    event.record['旅費'].value.forEach((row) => {
      const fields = row.value;
      const amount = Number(fields['旅費金額'].value);
      const required = TARGET_METHODS.includes(fields['手段'].value) &&
        Number.isFinite(amount) && amount > 0;

      validateLocation(fields['旅費出発地'], required, '出発地を入力してください。');
      validateLocation(fields['旅費到着地'], required, '到着地を入力してください。');
    });
    return event;
  });
})();

