(function () {
  'use strict';

  // 撮影用アプリ427の初期カスタマイズ。PCの追加・編集保存時に確認する。
  var THRESHOLD_YEN = 50000;
  var REASON_CODE = '高額申請の理由';
  var MESSAGE = '5万円以上の申請には、高額申請の理由を入力してください。';

  kintone.events.on(['app.record.create.submit', 'app.record.edit.submit'], function (event) {
    if (String(event.appId) !== '427') return event;
    var record = event.record;
    var reason = record[REASON_CODE];
    if (!reason || !record['精算金額']) return event;
    var amount = Number(record['精算金額'].value);
    if (Number.isFinite(amount) && amount >= THRESHOLD_YEN && !String(reason.value || '').trim()) {
      reason.error = MESSAGE;
    } else if (reason.error === MESSAGE) {
      // このJSが設定したエラーだけを解除し、ほかのチェック結果は維持する。
      reason.error = null;
    }
    return event;
  });
})();
